import{_ as l,a0 as t,w as o,s as c,I as a,x as n,a1 as i,A as e,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"使用 Lynis 扫描 Linux 安全性 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Lynis 扫描 Linux 安全性 | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Lynis 扫描 Linux 安全性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Lynis 扫描 Linux 安全性 | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20200512 Scan your Linux security with Lynis","title":"使用 Lynis 扫描 Linux 安全性","tag":"202010","desc":""},"relativePath":"202010/20200512 Scan your Linux security with Lynis.md","filePath":"[post].md"}'),d={name:"202010/20200512 Scan your Linux security with Lynis.md"};function g(h,s,u,k,y,b){const p=t("Link");return o(),c("div",null,[s[18]||(s[18]=a("h1",{id:"使用-lynis-扫描-linux-安全性",tabindex:"-1"},[n("使用 Lynis 扫描 Linux 安全性 "),a("a",{class:"header-anchor",href:"#使用-lynis-扫描-linux-安全性","aria-label":"Permalink to “使用 Lynis 扫描 Linux 安全性”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"使用这个全面的开源安全审计工具检查你的 Linux 机器的安全性。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202010/08/095516k6bdgeb6jhiajutm.jpg",alt:""})],-1)),s[21]||(s[21]=a("p",null,"你有没有想过你的 Linux 机器到底安全不安全？Linux 发行版众多，每个发行版都有自己的默认设置，你在上面运行着几十个版本各异的软件包，还有众多的服务在后台运行，而我们几乎不知道或不关心这些。",-1)),s[22]||(s[22]=a("p",null,"要想确定安全态势（指你的 Linux 机器上运行的软件、网络和服务的整体安全状态），你可以运行几个命令，得到一些零碎的相关信息，但你需要解析的数据量是巨大的。",-1)),a("p",null,[s[1]||(s[1]=n("如果能运行一个工具，生成一份关于机器安全状况的报告，那就好得多了。而幸运的是，有一个这样的软件：",-1)),i(p,{href:"https://github.com/CISOfy/lynis"},{default:e(()=>[...s[0]||(s[0]=[n("Lynis",-1)])]),_:1}),s[2]||(s[2]=n("。它是一个非常流行的开源安全审计工具，可以帮助强化基于 Linux 和 Unix 的系统。根据该项目的介绍：",-1))]),s[23]||(s[23]=r(`<blockquote><p>“它运行在系统本身，可以进行深入的安全扫描。主要目标是测试安全防御措施，并提供进一步强化系统的提示。它还将扫描一般系统信息、易受攻击的软件包和可能的配置问题。Lynis 常被系统管理员和审计人员用来评估其系统的安全防御。”</p></blockquote><h3 id="安装-lynis" tabindex="-1">安装 Lynis <a class="header-anchor" href="#安装-lynis" aria-label="Permalink to “安装 Lynis”">​</a></h3><p>你的 Linux 软件仓库中可能有 Lynis。如果有的话，你可以用以下方法安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf install lynis</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt install lynis</span></span></code></pre></div><p>然而，如果你的仓库中的版本不是最新的，你最好从 GitHub 上安装它。（我使用的是 Red Hat Linux 系统，但你可以在任何 Linux 发行版上运行它）。就像所有的工具一样，先在虚拟机上试一试是有意义的。要从 GitHub 上安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/redhat-release</span></span>
<span class="line"><span>Red Hat Enterprise Linux Server release 7.8 (Maipo)</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ uname  -r</span></span>
<span class="line"><span>3.10.0-1127.el7.x86_64</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ git clone https://github.com/CISOfy/lynis.git</span></span>
<span class="line"><span>Cloning into &#39;lynis&#39;...</span></span>
<span class="line"><span>remote: Enumerating objects: 30, done.</span></span>
<span class="line"><span>remote: Counting objects: 100% (30/30), done.</span></span>
<span class="line"><span>remote: Compressing objects: 100% (30/30), done.</span></span>
<span class="line"><span>remote: Total 12566 (delta 15), reused 8 (delta 0), pack-reused 12536</span></span>
<span class="line"><span>Receiving objects: 100% (12566/12566), 6.36 MiB | 911.00 KiB/s, done.</span></span>
<span class="line"><span>Resolving deltas: 100% (9264/9264), done.</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>一旦你克隆了这个版本库，那么进入该目录，看看里面有什么可用的。主要的工具在一个叫 <code>lynis</code> 的文件里。它实际上是一个 shell 脚本，所以你可以打开它看看它在做什么。事实上，Lynis 主要是用 shell 脚本来实现的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd lynis/</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>CHANGELOG.md        CONTRIBUTING.md  db           developer.prf  FAQ             include  LICENSE  lynis.8  README     SECURITY.md</span></span>
<span class="line"><span>CODE_OF_CONDUCT.md  CONTRIBUTORS.md  default.prf  extras         HAPPY_USERS.md  INSTALL  lynis    plugins  README.md</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ file lynis</span></span>
<span class="line"><span>lynis: POSIX shell script, ASCII text executable, with very long lines</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="运行-lynis" tabindex="-1">运行 Lynis <a class="header-anchor" href="#运行-lynis" aria-label="Permalink to “运行 Lynis”">​</a></h3><p>通过给 Lynis 一个 <code>-h</code> 选项来查看帮助部分，以便有个大概了解：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis -h</span></span></code></pre></div><p>你会看到一个简短的信息屏幕，然后是 Lynis 支持的所有子命令。</p><p>接下来，尝试一些测试命令以大致熟悉一下。要查看你正在使用的 Lynis 版本，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis show version</span></span>
<span class="line"><span>3.0.0</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>要查看 Lynis 中所有可用的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis show commands</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span>lynis audit</span></span>
<span class="line"><span>lynis configure</span></span>
<span class="line"><span>lynis generate</span></span>
<span class="line"><span>lynis show</span></span>
<span class="line"><span>lynis update</span></span>
<span class="line"><span>lynis upload-only</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="审计-linux-系统" tabindex="-1">审计 Linux 系统 <a class="header-anchor" href="#审计-linux-系统" aria-label="Permalink to “审计 Linux 系统”">​</a></h3><p>要审计你的系统的安全态势，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis audit system</span></span></code></pre></div><p>这个命令运行得很快，并会返回一份详细的报告，输出结果可能一开始看起来很吓人，但我将在下面引导你来阅读它。这个命令的输出也会被保存到一个日志文件中，所以你可以随时回过头来检查任何可能感兴趣的东西。</p><p>Lynis 将日志保存在这里：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  Files:</span></span>
<span class="line"><span>  - Test and debug information      : /var/log/lynis.log</span></span>
<span class="line"><span>  - Report data                     : /var/log/lynis-report.dat</span></span></code></pre></div><p>你可以验证是否创建了日志文件。它确实创建了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var/log/lynis.log</span></span>
<span class="line"><span>-rw-r-----. 1 root root 341489 Apr 30 05:52 /var/log/lynis.log</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ ls -l /var/log/lynis-report.dat</span></span>
<span class="line"><span>-rw-r-----. 1 root root 638 Apr 30 05:55 /var/log/lynis-report.dat</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="探索报告" tabindex="-1">探索报告 <a class="header-anchor" href="#探索报告" aria-label="Permalink to “探索报告”">​</a></h3><p>Lynis 提供了相当全面的报告，所以我将介绍一些重要的部分。作为初始化的一部分，Lynis 做的第一件事就是找出机器上运行的操作系统的完整信息。之后是检查是否安装了什么系统工具和插件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] Initializing program</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Detecting OS...                                           [ DONE ]</span></span>
<span class="line"><span>  - Checking profiles...                                      [ DONE ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ---------------------------------------------------</span></span>
<span class="line"><span>  Program version:           3.0.0</span></span>
<span class="line"><span>  Operating system:          Linux</span></span>
<span class="line"><span>  Operating system name:     Red Hat Enterprise Linux Server 7.8 (Maipo)</span></span>
<span class="line"><span>  Operating system version:  7.8</span></span>
<span class="line"><span>  Kernel version:            3.10.0</span></span>
<span class="line"><span>  Hardware platform:         x86_64</span></span>
<span class="line"><span>  Hostname:                  example</span></span>
<span class="line"><span>  ---------------------------------------------------</span></span>
<span class="line"><span>&lt;&lt;截断&gt;&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[+] System Tools</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Scanning available tools...</span></span>
<span class="line"><span>  - Checking system binaries...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[+] Plugins (phase 1)</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span> Note: plugins have more extensive tests and may take several minutes to complete</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>  - Plugin: pam</span></span>
<span class="line"><span>    [..]</span></span>
<span class="line"><span>  - Plugin: systemd</span></span>
<span class="line"><span>    [................]</span></span></code></pre></div><p>接下来，该报告被分为不同的部分，每个部分都以 <code>[+]</code> 符号开头。下面可以看到部分章节。（哇，要审核的地方有这么多，Lynis 是最合适的工具！）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] Boot and services</span></span>
<span class="line"><span>[+] Kernel</span></span>
<span class="line"><span>[+] Memory and Processes</span></span>
<span class="line"><span>[+] Users, Groups and Authentication</span></span>
<span class="line"><span>[+] Shells</span></span>
<span class="line"><span>[+] File systems</span></span>
<span class="line"><span>[+] USB Devices</span></span>
<span class="line"><span>[+] Storage</span></span>
<span class="line"><span>[+] NFS</span></span>
<span class="line"><span>[+] Name services</span></span>
<span class="line"><span>[+] Ports and packages</span></span>
<span class="line"><span>[+] Networking</span></span>
<span class="line"><span>[+] Printers and Spools</span></span>
<span class="line"><span>[+] Software: e-mail and messaging</span></span>
<span class="line"><span>[+] Software: firewalls</span></span>
<span class="line"><span>[+] Software: webserver</span></span>
<span class="line"><span>[+] SSH Support</span></span>
<span class="line"><span>[+] SNMP Support</span></span>
<span class="line"><span>[+] Databases</span></span>
<span class="line"><span>[+] LDAP Services</span></span>
<span class="line"><span>[+] PHP</span></span>
<span class="line"><span>[+] Squid Support</span></span>
<span class="line"><span>[+] Logging and files</span></span>
<span class="line"><span>[+] Insecure services</span></span>
<span class="line"><span>[+] Banners and identification</span></span>
<span class="line"><span>[+] Scheduled tasks</span></span>
<span class="line"><span>[+] Accounting</span></span>
<span class="line"><span>[+] Time and Synchronization</span></span>
<span class="line"><span>[+] Cryptography</span></span>
<span class="line"><span>[+] Virtualization</span></span>
<span class="line"><span>[+] Containers</span></span>
<span class="line"><span>[+] Security frameworks</span></span>
<span class="line"><span>[+] Software: file integrity</span></span>
<span class="line"><span>[+] Software: System tooling</span></span>
<span class="line"><span>[+] Software: Malware</span></span>
<span class="line"><span>[+] File Permissions</span></span>
<span class="line"><span>[+] Home directories</span></span>
<span class="line"><span>[+] Kernel Hardening</span></span>
<span class="line"><span>[+] Hardening</span></span>
<span class="line"><span>[+] Custom tests</span></span></code></pre></div><p>Lynis 使用颜色编码使报告更容易解读。</p><ul><li>绿色。一切正常</li><li>黄色。跳过、未找到，可能有个建议</li><li>红色。你可能需要仔细看看这个</li></ul><p>在我的案例中，大部分的红色标记都是在 “Kernel Hardening” 部分找到的。内核有各种可调整的设置，它们定义了内核的功能，其中一些可调整的设置可能有其安全场景。发行版可能因为各种原因没有默认设置这些，但是你应该检查每一项，看看你是否需要根据你的安全态势来改变它的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] Kernel Hardening</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Comparing sysctl key pairs with scan profile</span></span>
<span class="line"><span>    - fs.protected_hardlinks (exp: 1)                         [ OK ]</span></span>
<span class="line"><span>    - fs.protected_symlinks (exp: 1)                          [ OK ]</span></span>
<span class="line"><span>    - fs.suid_dumpable (exp: 0)                               [ OK ]</span></span>
<span class="line"><span>    - kernel.core_uses_pid (exp: 1)                           [ OK ]</span></span>
<span class="line"><span>    - kernel.ctrl-alt-del (exp: 0)                            [ OK ]</span></span>
<span class="line"><span>    - kernel.dmesg_restrict (exp: 1)                          [ DIFFERENT ]</span></span>
<span class="line"><span>    - kernel.kptr_restrict (exp: 2)                           [ DIFFERENT ]</span></span>
<span class="line"><span>    - kernel.randomize_va_space (exp: 2)                      [ OK ]</span></span>
<span class="line"><span>    - kernel.sysrq (exp: 0)                                   [ DIFFERENT ]</span></span>
<span class="line"><span>    - kernel.yama.ptrace_scope (exp: 1 2 3)                   [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.accept_redirects (exp: 0)             [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.accept_source_route (exp: 0)          [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.bootp_relay (exp: 0)                  [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.forwarding (exp: 0)                   [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.log_martians (exp: 1)                 [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.mc_forwarding (exp: 0)                [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.proxy_arp (exp: 0)                    [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.rp_filter (exp: 1)                    [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.send_redirects (exp: 0)               [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.default.accept_redirects (exp: 0)         [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.default.accept_source_route (exp: 0)      [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.default.log_martians (exp: 1)             [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.icmp_echo_ignore_broadcasts (exp: 1)           [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.icmp_ignore_bogus_error_responses (exp: 1)     [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.tcp_syncookies (exp: 1)                        [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.tcp_timestamps (exp: 0 1)                      [ OK ]</span></span>
<span class="line"><span>    - net.ipv6.conf.all.accept_redirects (exp: 0)             [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv6.conf.all.accept_source_route (exp: 0)          [ OK ]</span></span>
<span class="line"><span>    - net.ipv6.conf.default.accept_redirects (exp: 0)         [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv6.conf.default.accept_source_route (exp: 0)      [ OK ]</span></span></code></pre></div><p>看看 SSH 这个例子，因为它是一个需要保证安全的关键领域。这里没有什么红色的东西，但是 Lynis 对我的环境给出了很多强化 SSH 服务的建议：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] SSH Support</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Checking running SSH daemon                               [ FOUND ]</span></span>
<span class="line"><span>    - Searching SSH configuration                             [ FOUND ]</span></span>
<span class="line"><span>    - OpenSSH option: AllowTcpForwarding                      [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: ClientAliveCountMax                     [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: ClientAliveInterval                     [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: Compression                             [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: FingerprintHash                         [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: GatewayPorts                            [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: IgnoreRhosts                            [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: LoginGraceTime                          [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: LogLevel                                [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: MaxAuthTries                            [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: MaxSessions                             [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: PermitRootLogin                         [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: PermitUserEnvironment                   [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: PermitTunnel                            [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: Port                                    [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: PrintLastLog                            [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: StrictModes                             [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: TCPKeepAlive                            [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: UseDNS                                  [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: X11Forwarding                           [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: AllowAgentForwarding                    [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: UsePrivilegeSeparation                  [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: AllowUsers                              [ NOT FOUND ]</span></span>
<span class="line"><span>    - OpenSSH option: AllowGroups                             [ NOT FOUND ]</span></span></code></pre></div><p>我的系统上没有运行虚拟机或容器，所以这些显示的结果是空的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] Virtualization</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[+] Containers</span></span>
<span class="line"><span>------------------------------------</span></span></code></pre></div><p>Lynis 会检查一些从安全角度看很重要的文件的文件权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] File Permissions</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Starting file permissions check</span></span>
<span class="line"><span>    File: /boot/grub2/grub.cfg                                [ SUGGESTION ]</span></span>
<span class="line"><span>    File: /etc/cron.deny                                      [ OK ]</span></span>
<span class="line"><span>    File: /etc/crontab                                        [ SUGGESTION ]</span></span>
<span class="line"><span>    File: /etc/group                                          [ OK ]</span></span>
<span class="line"><span>    File: /etc/group-                                         [ OK ]</span></span>
<span class="line"><span>    File: /etc/hosts.allow                                    [ OK ]</span></span>
<span class="line"><span>    File: /etc/hosts.deny                                     [ OK ]</span></span>
<span class="line"><span>    File: /etc/issue                                          [ OK ]</span></span>
<span class="line"><span>    File: /etc/issue.net                                      [ OK ]</span></span>
<span class="line"><span>    File: /etc/motd                                           [ OK ]</span></span>
<span class="line"><span>    File: /etc/passwd                                         [ OK ]</span></span>
<span class="line"><span>    File: /etc/passwd-                                        [ OK ]</span></span>
<span class="line"><span>    File: /etc/ssh/sshd_config                                [ OK ]</span></span>
<span class="line"><span>    Directory: /root/.ssh                                     [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.d                                    [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.daily                                [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.hourly                               [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.weekly                               [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.monthly                              [ SUGGESTION ]</span></span></code></pre></div><p>在报告的底部，Lynis 根据报告的发现提出了建议。每项建议后面都有一个 “TEST-ID”（为了下一部分方便，请将其保存起来）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> Suggestions (47):</span></span>
<span class="line"><span>  ----------------------------</span></span>
<span class="line"><span>  * If not required, consider explicit disabling of core dump in /etc/security/limits.conf file [KRNL-5820]</span></span>
<span class="line"><span>      https://cisofy.com/lynis/controls/KRNL-5820/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  * Check PAM configuration, add rounds if applicable and expire passwords to encrypt with new values [AUTH-9229]</span></span>
<span class="line"><span>      https://cisofy.com/lynis/controls/AUTH-9229/</span></span></code></pre></div><p>Lynis 提供了一个选项来查找关于每个建议的更多信息，你可以使用 <code>show details</code> 命令和 TEST-ID 号来访问：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./lynis show details TEST-ID</span></span></code></pre></div><p>这将显示该测试的其他信息。例如，我检查了 SSH-7408 的详细信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis show details SSH-7408</span></span>
<span class="line"><span>2020-04-30 05:52:23 Performing test ID SSH-7408 (Check SSH specific defined options)</span></span>
<span class="line"><span>2020-04-30 05:52:23 Test: Checking specific defined options in /tmp/lynis.k8JwazmKc6</span></span>
<span class="line"><span>2020-04-30 05:52:23 Result: added additional options for OpenSSH &amp;lt; 7.5</span></span>
<span class="line"><span>2020-04-30 05:52:23 Test: Checking AllowTcpForwarding in /tmp/lynis.k8JwazmKc6</span></span>
<span class="line"><span>2020-04-30 05:52:23 Result: Option AllowTcpForwarding found</span></span>
<span class="line"><span>2020-04-30 05:52:23 Result: Option AllowTcpForwarding value is YES</span></span>
<span class="line"><span>2020-04-30 05:52:23 Result: OpenSSH option AllowTcpForwarding is in a weak configuration state and should be fixed</span></span>
<span class="line"><span>2020-04-30 05:52:23 Suggestion: Consider hardening SSH configuration [test:SSH-7408] [details:AllowTcpForwarding (set YES to NO)] [solution:-]</span></span></code></pre></div><h3 id="试试吧" tabindex="-1">试试吧 <a class="header-anchor" href="#试试吧" aria-label="Permalink to “试试吧”">​</a></h3><p>如果你想更多地了解你的 Linux 机器的安全性，请试试 Lynis。如果你想了解 Lynis 是如何工作的，可以研究一下它的 shell 脚本，看看它是如何收集这些信息的。</p><hr>`,50)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),i(p,{href:"https://opensource.com/article/20/5/linux-security-lynis"},{default:e(()=>[...s[3]||(s[3]=[n("https://opensource.com/article/20/5/linux-security-lynis",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=n("作者：",-1)),i(p,{href:"https://opensource.com/users/gkamathe"},{default:e(()=>[...s[5]||(s[5]=[n("Gaurav Kamathe",-1)])]),_:1}),s[10]||(s[10]=n(" 选题：",-1)),i(p,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 译者：",-1)),i(p,{href:"https://github.com/wxy"},{default:e(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1}),s[12]||(s[12]=n(" 校对：",-1)),i(p,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=n("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原创编译，",-1)),i(p,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[n("Linux中国",-1)])]),_:1}),s[17]||(s[17]=n(" 荣誉推出",-1))])])}const x=l(d,[["render",g]]);export{m as __pageData,x as default};
